  "image_category": "MARKING_AND_SIGNAL",
  "summary": "Hình ảnh minh họa bố trí vạch dừng xe (Vạch 7.1) và vạch người đi bộ qua đường (Vạch 7.3) tại nút giao thông có đèn tín hiệu, kèm kích thước quy chuẩn theo QCVN 41:2024/BGTVT.",
  "items": [
    {
      "identifier": "Vạch dừng xe (Vạch 7.1)",
      "visual_or_geometric_features": "Vạch liền nét màu trắng, bề rộng 20 cm hoặc 30 cm hoặc 40 cm (tùy cấp đường), kẻ ngang toàn bộ bề rộng đường hướng xe chạy. Trên vạch có chữ 'STOP' màu trắng, đỉnh chữ cách mép vạch từ 2,0 m đến 3,0 m.",
      "meaning_or_specification": "Dùng để xác định vị trí dừng xe khi có tín hiệu đèn đỏ hoặc biển số R.122. Lái xe phải dừng lại trước vạch này."
    },
    {
      "identifier": "Vạch người đi bộ qua đường (Vạch 7.3 - Mẫu 1)",
      "visual_or_geometric_features": "Các đường vạch đậm liền song song màu trắng (vạch ngựa vằn), bề rộng mỗi vạch 40 cm, chiều dài vạch 40 cm, cách nhau 40 cm. Tổng chiều rộng khu vực vạch là 1,8 m.",
      "meaning_or_specification": "Xác định phạm vi phần đường dành cho người đi bộ cắt qua đường. Xe cơ giới phải dừng lại trước vạch dừng xe khi có tín hiệu đèn đỏ hoặc khi có người đi bộ qua đường."
    },
    {
      "identifier": "Khoảng cách giữa vạch dừng xe và vạch người đi bộ",
      "visual_or_geometric_features": "Khoảng cách từ mép vạch dừng xe đến mép vạch người đi bộ qua đường được ghi là 1,5 m - 3,0 m.",
      "meaning_or_specification": "Theo quy định, nếu trên nhánh dẫn có bố trí vạch người đi bộ, vạch dừng xe nên đặt cách mép vạch người đi bộ từ 1,5 m đến 3,0 m để đảm bảo an toàn và tầm nhìn."
    }
  ]
